import {registerCatalog,localizedText} from './i18n.js';
import {displayNumber,precisionInputAttributes,readPrecisionInput,bindPrecisionInput} from './number-display.js';
import {calculateResearchOperating} from './research-model.js';
import {allocateNvmiCommon,NVMI_CLAIM_DEFAULTS,NVMI_INFERRED_MARKET_PRICE} from './nvmi-conditional-allocation.js';
const copy={
 title:['Optional NVMI common allocation','可选 NVMI 普通股价值分配'],
 off:['Operating EV only (default)','仅营业企业价值（默认）'],conditional:['Analyst-conditional allocation','分析师条件估计分配'],market:['Fixed-market-claim reference','固定市场债权参考'],
 scope:['Capital origin: December 31, 2025. Information through October 18, 2026. Later-information estimate, not a current fair value or price target. The primary EV and its Monte Carlo remain unchanged.','资本基准日：2025年12月31日；信息截至2026年10月18日。使用后续信息的估计，并非当前公允价值或目标价。主要企业价值及其蒙特卡洛计算保持不变。'],
 proxy:['No-early-event matched-strip approximation: discounted straight debt plus 40 daily conversion calls; hedge is 40 daily call spreads. Uses simplified 252-day spacing and common maturity payment. This is not a contract-complete convertible model.','无提前事件的匹配期权条带近似：折现普通债务加40个每日转换期权；对冲为40个每日看涨期权价差。采用简化的252日间隔及到期统一付款。这不是完整可转债合约模型。'],
 exclusions:['Early conversion, issuer soft calls, make-whole, fundamental-change puts, joint equity/default dynamics, dealer default and settlement-election differences are omitted. Matching strike legs cancel only in this surrogate, not legally.','未建模提前转换、发行人有条件赎回、补偿性转换调整、重大变化回售、股权与违约联动、交易对手违约及结算选择差异。匹配执行价的期权仅在本近似模型中抵消，并非法律上的完全对冲。'],
 estimates:['All editable parameters are analyst estimates. Volatility defaults to a 50.08% sector equity proxy; the flat continuously compounded rate comes from a 3.73% Treasury par yield, not a zero curve. Credit spread 150 bp is assumed. Zero dividends continue the historical policy. RSU multiplier 1 is not a contractual maximum. Residual $5m is an allowance, not a discovered liability.','所有可编辑参数均为分析师估计。波动率默认使用50.08%的行业股权代理值；连续复利平坦利率由3.73%的美国国债票面收益率转换，并非零息曲线。信用利差假设为150基点。零股息延续历史政策。受限股单位倍数1并非合约上限。500万美元剩余索偿为假设预留，而非已发现负债。'],
 volatility:['Equity volatility · %','股权波动率 · %'],rate:['Risk-free rate · continuously compounded %','无风险利率 · 连续复利 %'],spread:['Credit spread · continuously compounded %','信用利差 · 连续复利 %'],dividend:['Dividend yield · continuously compounded %','股息率 · 连续复利 %'],haircut:['Hedge value haircut · %','对冲价值折减 · %'],rsuMultiplier:['RSU payout / vesting multiplier','受限股单位支付／归属倍数'],residual:['Additional residual claims · USD m','额外剩余索偿 · 百万美元'],mismatch:['Conversion mismatch allowance · USD m','转换不匹配预留 · 百万美元'],
 common:['Conditional common value · USD / share','条件普通股价值 · 美元／股'],equity:['Existing common equity · USD m','现有普通股权益 · 百万美元'],ev:['Selected operating EV · USD m','所选营业企业价值 · 百万美元'],assets:['Assets before allocated claims · USD m','分配索偿前资产 · 百万美元'],rsu:['Legacy RSU claim · USD m','存量受限股单位索偿 · 百万美元'],options:['Legacy option claim · USD m','存量期权索偿 · 百万美元'],convert:['Convertible claim proxy · USD m','可转债索偿代理值 · 百万美元'],hedge:['Capped-call asset proxy · USD m','封顶看涨期权资产代理值 · 百万美元'],bond:['Straight-bond component · USD m','普通债务部分 · 百万美元'],
 marketNote:['Separate fixed-market reference: deduct the full observed December convertible quote of $936.27m once. Hedge and employee options are estimates at the inferred rounded filing-implied stock input of {price}; they are not jointly solved at intrinsic common value. This is not calibration of the conditional method.','独立固定市场参考：完整扣除12月观察到的936.27百万美元可转债报价一次。对冲及员工期权按申报数据推算的约数股价 {price} 估计，并非基于内生普通股价值联合求解。这不是对条件估计方法的校准。'],
 invalid:['Enter finite values: volatility, spread, dividend yield and allowances must be nonnegative; haircut 0–100%; RSU multiplier ≥ 0. Blank is unknown, not zero.','请输入有限数值：波动率、利差、股息率和预留不得为负；折减为0–100%；受限股倍数≥0。空白表示未知，而非零。'],range:['These inputs exceed the numerical range; no allocation is shown.','这些输入超出数值计算范围；不显示价值分配。'],none:['No positive common-allocation solution at these inputs. Senior-claim shortfall at zero common value: USD {shortfall}m. This does not model a bankruptcy recovery waterfall.','在这些输入下不存在正的普通股分配解。普通股价值为零时的优先索偿缺口：{shortfall} 百万美元。这不是破产回收顺序模型。'],
 diagnostics:['Selected one-at-a-time diagnostics · USD / share','选定单因素诊断 · 美元／股'],face:['Face-value bond convention','债务按面值惯例'],noHedge:['No hedge credit','不计对冲资产'],extra:['Additional $25m mismatch','额外2500万美元不匹配预留'],limits:['Diagnostics are illustrative, not confidence intervals or worst-case bounds. All omitted event/default assumptions remain fixed. Higher spreads release common value at fixed EV; this is not a complete distress scenario.','诊断仅供说明，不是置信区间或最坏情况边界。所有未建模的事件／违约假设保持不变。固定企业价值下更高利差会释放普通股价值；这不是完整的困境情景。'],
 mc:['NVMI Monte Carlo is operating-EV only. This optional proxy is not repriced per trial and produces no common-share Monte Carlo distribution.','NVMI 蒙特卡洛仅计算营业企业价值。此可选代理模型不在每次试验中重新定价，也不生成普通股蒙特卡洛分布。'],method:['Method and source notes','方法与来源说明'],reset:['Reset allocation estimates','重置分配估计'],date:['This allocation requires the original December 31, 2025 timing. Restore origin timing to use it.','此分配要求使用原始2025年12月31日时点。请恢复基准时点以使用。'],conservation:['No second deduction of principal, RSUs or exercise proceeds; underlying convertible shares are not added. Future compensation stays in operating FCFF; historical hedge premium is not credited again.','本金、受限股单位或行权收入不重复扣除；可转债对应股数不增加到分母。未来薪酬保留在营业自由现金流中；历史对冲权利金不重复计入。']};
registerCatalog('nvmiClaims',{en:Object.fromEntries(Object.entries(copy).map(([k,v])=>[k,v[0]])),'zh-Hans':Object.fromEntries(Object.entries(copy).map(([k,v])=>[k,v[1]]))});
const l=(k,p={})=>localizedText('nvmiClaims.'+k,p),n=x=>displayNumber(x,2),fields=Object.keys(NVMI_CLAIM_DEFAULTS),percent=new Set(['volatility','rate','spread','dividend','haircut']);
export const nvmiMonteCarloNoteHTML=()=>`<p class="micro">${l('mc')}</p>`;
export function nvmiConditionalResult(d){if(d.ticker!=='NVMI'||!['conditional','market'].includes(d.nvmiConditional?.mode))return null;if(d.timing?.mode!=='origin'||d.discountOrigin!=='2025-12-31')throw Error('date');return allocateNvmiCommon(calculateResearchOperating(d).enterprise,d.nvmiConditional.inputs,d.nvmiConditional.mode);}
export function nvmiConditionalOutputHTML(d){
 try{const r=nvmiConditionalResult(d);if(!r)return '';if(r.status==='no-positive-common')return `<p class="research-warning">${l('none',{shortfall:n(r.shortfall)})}</p>`;
 const rows=[['common',r.perShare],['equity',r.commonEquity],['ev',calculateResearchOperating(d).enterprise],['assets',r.assets],['rsu',r.rsuClaim],['options',r.optionClaim],['convert',r.convertClaim],['hedge',r.hedgeAsset],...(r.mode==='conditional'?[['bond',r.bondValue]]:[])];
 const diagnostic=r.mode==='conditional'?`<h4>${l('diagnostics')}</h4><dl>${[['face',allocateNvmiCommon(calculateResearchOperating(d).enterprise,r.inputs,'conditional','face')],['noHedge',allocateNvmiCommon(calculateResearchOperating(d).enterprise,{...r.inputs,haircut:1})],['extra',allocateNvmiCommon(calculateResearchOperating(d).enterprise,{...r.inputs,mismatch:r.inputs.mismatch+25})]].map(([k,v])=>`<dt>${l(k)}</dt><dd>${v.perShare===null?l('none',{shortfall:n(v.shortfall)}):n(v.perShare)}</dd>`).join('')}</dl><p class="micro">${l('limits')}</p>`:'';
 return `<dl>${rows.map(([k,v])=>`<dt>${l(k)}</dt><dd>${n(v)}</dd>`).join('')}</dl>${r.mode==='market'?`<p>${l('marketNote',{price:n(NVMI_INFERRED_MARKET_PRICE)})}</p>`:''}${diagnostic}`;
 }catch(e){return `<p class="research-warning" role="alert">${l(['range','date'].includes(e.message)?e.message:'invalid')}</p>`;}
}
export function nvmiConditionalEditorHTML(d){
 const state=d.nvmiConditional||{mode:'off',inputs:{}},active=['conditional','market'].includes(state.mode),p={...NVMI_CLAIM_DEFAULTS,...state.inputs};
 return `<section class="research-card" id="nvmi-conditional-tool"><h3>${l('title')}</h3><div class="research-actions">${['off','conditional','market'].map(mode=>`<button type="button" class="quiet" data-nvmi-mode="${mode}" aria-pressed="${state.mode===mode}">${l(mode)}</button>`).join('')}</div><p>${l('scope')}</p>${nvmiMonteCarloNoteHTML()}${active?`<p>${l('proxy')}</p><p class="micro">${l('exclusions')}</p><p class="micro">${l('estimates')}</p><div class="research-field-grid">${fields.filter(k=>state.mode!=='market'||!['spread','mismatch'].includes(k)).map(k=>{const scale=percent.has(k)?100:1;return `<label>${l(k)}<input type="number" step="any" inputmode="decimal" data-nvmi-input="${k}" data-scale="${scale}" ${precisionInputAttributes(p[k],scale)}></label>`;}).join('')}</div><button type="button" class="quiet" data-nvmi-reset>${l('reset')}</button><div id="nvmi-conditional-output" aria-live="polite">${nvmiConditionalOutputHTML(d)}</div><p class="micro">${l('conservation')}</p><a href="./data/nvmi-conditional-method-v1.html" target="_blank" rel="noopener">${l('method')}</a>`:''}</section>`;
}
export function bindNvmiConditional(root,d,{save,rerender,remember,endEdit}={}){
 root.querySelectorAll('[data-nvmi-mode]').forEach(el=>el.onclick=()=>{const focused=el.ownerDocument?.activeElement===el;remember?.('nvmi-mode');d.nvmiConditional={mode:el.dataset.nvmiMode,inputs:d.nvmiConditional?.inputs||{}};save();rerender();if(focused)root.querySelector(`[data-nvmi-mode="${el.dataset.nvmiMode}"]`)?.focus({preventScroll:true});});
 const reset=root.querySelector('[data-nvmi-reset]');if(reset)reset.onclick=()=>{const focused=reset.ownerDocument?.activeElement===reset;remember?.('nvmi-reset');d.nvmiConditional.inputs={};save();rerender();if(focused)root.querySelector('[data-nvmi-reset]')?.focus({preventScroll:true});};
 root.querySelectorAll('[data-nvmi-input]').forEach(el=>{el.onfocus=()=>endEdit?.();el.onblur=()=>endEdit?.();el.oninput=()=>{remember?.('nvmi:'+el.dataset.nvmiInput);d.nvmiConditional.inputs||={};d.nvmiConditional.inputs[el.dataset.nvmiInput]=readPrecisionInput(el,Number(el.dataset.scale));save();const out=root.querySelector('#nvmi-conditional-output');if(out)out.innerHTML=nvmiConditionalOutputHTML(d);};bindPrecisionInput(el);});
}
